insert into public.content_items(id,kind,payload,content_hash) values
('adhkar-waking','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-waking","meaning_older":"حين تصحو تشكر الله على يوم جديد أعطاك إياه. وفي الذكر معنى أبعد: كما أيقظك اليوم بعد نومك، يبعث الناس يوم القيامة بعد موتهم — فالرجوع إليه في الحالين.","meaning_young":"أول ما تستيقظ من النوم، تشكر الله. أنت كنت نائماً لا تعرف شيئاً عن الدنيا، ثم فتحت عينيك من جديد — وهذه نعمة من الله.","options":["لأنه أعطانا يوماً جديداً نعيشه","لأن النوم كان مريحاً","لأن الصباح جميل"],"pack":"adhkar","pose":"standing","question":"لماذا نشكر الله حين نستيقظ؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"morning","scene_mode":"generated","situation":"الاستيقاظ","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي أَحْيَانَا بَعْدَمَا أَمَاتَنَا وَإِلَيْهِ النُّشُورُ"}'::jsonb,'4e79ecc69328352f538a79c0be47b41e8bd5dc6f8340299b3df33da021d4aa71'),
('adhkar-dressing','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-dressing","meaning_older":"تشكر الله على ثوب يسترك ويدفئك. وتتذكر أنك لم تحصل عليه بقوتك وحدك: الله هو الذي يسّره لك ورزقك إياه، وغيرك قد لا يجد مثله.","meaning_young":"حين تلبس ثوبك تشكر الله. فهو الذي أعطاك إياه، وأنت لم تصنعه بنفسك.","options":["أن الله هو الذي رزقنا إياه","أن الثوب غالي الثمن","أن لوننا المفضل جميل"],"pack":"adhkar","pose":"standing","question":"ماذا نتذكّر حين نلبس ثوبنا؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"home","scene_mode":"generated","situation":"لبس الثياب","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا الثَّوْبَ وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّة"}'::jsonb,'681dbded5f17e7d4ae41af4fa7a0abc04fcac281fef59c4ff5675995efa4419f'),
('adhkar-food-before','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-food-before","meaning_older":"قبل الطعام تطلب من الله أن يبارك لك فيه: أن يكون نافعاً لجسمك ومعيناً لك على الخير. وتطلب منه أن ينجّيك ويحفظك. ثم تبدأ أكلك ذاكراً اسم من رزقك إياه.","meaning_young":"قبل أن تأكل، تسأل الله أن يجعل طعامك خيراً لك. وتطلب منه أن يحفظك ويحميك، ثم تبدأ أكلك ذاكراً اسمه.","options":["أن يجعل الطعام خيراً ونافعاً لنا","أن يكون الطعام لذيذاً","أن نأكل كثيراً"],"pack":"adhkar","pose":"sitting","question":"ماذا نطلب من الله قبل الطعام؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"food","scene_mode":"generated","situation":"الطعام","source":"TODO_REVIEW","text":"اللَّهُمَّ بَارِكْ لَنَا فِيمَا رَزَقْتَنَا، وَقِنَا عَذَابَ النَّارِ، بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ"}'::jsonb,'fd4013c2e18d88e0f414349d52ef308196b674d3a634c82a159464141bf1a5f2'),
('adhkar-food-after','lesson','{"answer":0,"grade":"TODO_REVIEW","id":"adhkar-food-after","meaning_older":"بعد الطعام تشكر الله على نعمتين: نعمة الطعام والشراب التي يحتاجها جسمك، ونعمة الهداية إلى دينه وهي أعظم منهما. فالذكر يذكّرك أن أكبر ما أُعطيت ليس ما في الصحن.","meaning_young":"بعد أن تأكل وتشرب، تشكر الله على طعامك وعلى الماء. وتشكره على نعمة أكبر منهما: أن هداك إلى دينه.","options":["نعمة أن جعلنا مسلمين","نعمة الأصدقاء","نعمة البيت"],"pack":"adhkar","pose":"sitting","question":"على أي نعمة نشكر الله في هذا الذكر غير الطعام والشراب؟","review":{"date":null,"reviewer":null,"status":"pending"},"scene":"food","scene_mode":"generated","situation":"الطعام","source":"TODO_REVIEW","text":"الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنَا وَسَقَانَا وَجَعَلَنَا مُسْلِمِينَ"}'::jsonb,'d04cddad2ec3fc585b67ec5bc0638eb05fba861f4c90c4655dbf5c37fb445d07')
